@namespace sv_10a32dcdb8dc491292d74ecb83e1493e.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12"
                  class="cover-letter-textarea"
                  maxlength="@MaxLength"
                  value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <span class="char-count @(CharCount > MaxLength ? "over-limit" : "")">
            @CharCount / @MaxLength characters
        </span>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private int CharCount => CoverLetter?.Length ?? 0;

    private async Task HandleInput(ChangeEventArgs e)
    {
        CoverLetter = (string?)e.Value ?? "";
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

