.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    color: #1e3a5f;
    font-size: 1rem;
}

.review-grid {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-grid dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
