arguments.file_text:
@page "/apply"
@using sv_10a32dcdb8dc491292d74ecb83e1493e.Models
@namespace sv_10a32dcdb8dc491292d74ecb83e1493e.Components.Pages.Apply
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@_personalInfo"
                              ValidateEmail="ValidateEmailAsync"
                              OnNext="() => AdvanceStep(0)" />
            break;
        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnNext="() => AdvanceStep(1)"
                             OnBack="() => GoToStep(_currentStep - 1)" />
            break;
        case 2:
            <ReferencesStep References="@_references"
                            OnNext="() => AdvanceStep(2)"
                            OnBack="() => GoToStep(_currentStep - 1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="val => _coverLetter = val"
                             OnNext="() => AdvanceStep(3)"
                             OnBack="() => GoToStep(_currentStep - 1)" />
            break;
        case 4:
            <ReviewStep PersonalInfo="@_personalInfo"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(_currentStep - 1)"
                        OnEditStep="GoToStep"
                        OnSubmit="SubmitAsync" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int _currentStep;
    private readonly HashSet<int> _completedSteps = [];

    private readonly PersonalInfoStep.PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryForm.WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceForm.ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    private void AdvanceStep(int completedStep)
    {
        _completedSteps.Add(completedStep);
        _currentStep = completedStep + 1;
    }

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
        {
            _currentStep = step;
        }
    }

    private async Task<bool> ValidateEmailAsync(string email)
    {
        return await ApplicationService.ValidateEmailAsync(email);
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            new WorkHistory(_workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-container {
    max-width: 52rem;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

.apply-container h1 {
    margin-bottom: 1.5rem;
    color: #1e3a5f;
    font-size: 1.75rem;
}

/* Shared form styles used across steps */
::deep .step-content h2 {
    margin-bottom: 1.25rem;
    color: #1e3a5f;
    font-size: 1.25rem;
    border-bottom: 2px solid #e5e7eb;
    padding-bottom: 0.5rem;
}

::deep .form-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 1rem;
}

::deep .form-group label {
    font-size: 0.875rem;
    font-weight: 500;
    color: #374151;
    margin-bottom: 0.25rem;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="tel"],
::deep .form-group input[type="date"],
::deep .form-group textarea {
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.925rem;
    font-family: inherit;
    transition: border-color 0.15s;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

::deep .validation-hint {
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

::deep .error-banner {
    background-color: #fef2f2;
    color: #991b1b;
    border: 1px solid #fecaca;
    border-radius: 0.375rem;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

::deep .step-actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e5e7eb;
}

::deep .btn-primary {
    background-color: #3b82f6;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.925rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

::deep .btn-primary:hover:not(:disabled) {
    background-color: #2563eb;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-outline {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.925rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

::deep .btn-outline:hover {
    background-color: #f9fafb;
}

::deep .btn-secondary {
    background: white;
    color: #3b82f6;
    border: 1px dashed #93c5fd;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    cursor: pointer;
    width: 100%;
    margin-top: 0.5rem;
}

::deep .btn-secondary:hover {
    background-color: #eff6ff;
}

::deep .btn-link {
    background: none;
    border: none;
    color: #3b82f6;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

::deep .btn-link:hover {
    color: #2563eb;
}

