@namespace sv_10a32dcdb8dc491292d74ecb83e1493e.Components.Pages.Apply

<fieldset class="work-entry-card">
    <legend>Position @(Index + 1)</legend>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => { Entry.Company = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => { Entry.Title = (string?)e.Value ?? string.Empty; NotifyChanged(); }" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="HandleStartDateChange" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd"))"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool?)e.Value ?? false)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => { Entry.Description = (string?)e.Value ?? string.Empty; NotifyChanged(); }"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void NotifyChanged() => OnChanged.InvokeAsync(Entry);

    private void HandleStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var date))
            Entry.StartDate = date;
        NotifyChanged();
    }

    private void HandleEndDateChange(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        Entry.EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void ToggleCurrent(bool isCurrent)
    {
        Entry.IsCurrent = isCurrent;
        if (isCurrent) Entry.EndDate = null;
        NotifyChanged();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

